#!/usr/bin/env python3
"""fblog - a small tool to view json log files (Python reimplementation)."""

import argparse
import json
import os
import re
import sys
from collections import OrderedDict

# ---------------------------------------------------------------------------
# ANSI helpers
# ---------------------------------------------------------------------------

RESET = "\x1b[0m"


def _wrap(code, text):
    return f"\x1b[{code}m{text}{RESET}"


def bold(text):
    return _wrap("1", text)


def dim(text):
    return _wrap("2", text)


def red(text):
    return _wrap("31", text)


def green(text):
    return _wrap("32", text)


def yellow(text):
    return _wrap("33", text)


def blue(text):
    return _wrap("34", text)


def purple(text):
    return _wrap("35", text)


def cyan(text):
    return _wrap("36", text)


def color_rgb(r, g, b, text):
    return f"\x1b[38;2;{int(r)};{int(g)};{int(b)}m{text}{RESET}"


def level_style(text):
    lvl = _strip_ansi(text).strip().lower()
    color_map = {
        "trace": "1;36",
        "debug": "1;34",
        "info": "1;32",
        "warn": "1;33",
        "warning": "1;33",
        "error": "1;31",
    }
    code = color_map.get(lvl, "1;35")
    return _wrap(code, text)


_ansi_re = re.compile(r"\x1b\[[0-9;]*m")


def _strip_ansi(text):
    return _ansi_re.sub("", text)


def _visible_len(text):
    return len(_strip_ansi(text))


def fixed_size(n, text):
    n = int(n)
    visible = _visible_len(text)
    if visible < n:
        return " " * (n - visible) + text
    if visible > n:
        # truncate accounting for ansi
        return _truncate(text, n)
    return text


def min_size(n, text):
    n = int(n)
    visible = _visible_len(text)
    if visible < n:
        return " " * (n - visible) + text
    return text


def _truncate(text, n):
    """Truncate visible characters of a string that may contain ANSI escapes."""
    result = []
    visible = 0
    i = 0
    while i < len(text) and visible < n:
        if text[i] == "\x1b":
            # Copy ANSI sequence as-is
            m = _ansi_re.match(text, i)
            if m:
                result.append(m.group(0))
                i = m.end()
                continue
        result.append(text[i])
        visible += 1
        i += 1
    return "".join(result)


def uppercase(text):
    # Upper-case only the text parts, preserving ANSI escapes.
    def up_part(match):
        return ""  # placeholder handled below

    parts = _ansi_re.split(text)
    codes = _ansi_re.findall(text)
    out = []
    for i, p in enumerate(parts):
        if i > 0 and i - 1 < len(codes):
            out.append(codes[i - 1])
        out.append(p.upper())
    return "".join(out)


# ---------------------------------------------------------------------------
# Timestamp formatting
# ---------------------------------------------------------------------------

def format_timestamp(value):
    """Given a JSON value, return a string timestamp.

    Rules:
    - If value is a number or numeric string, interpret as Unix time.
      If magnitude >= 1e10, treat as milliseconds.
      Otherwise seconds.
      If out of range, return the number as string.
    - If value is string (non-numeric), return as is.
    - Else return json-encoded.
    """
    import datetime

    def maybe_int(v):
        try:
            return int(v)
        except Exception:
            return None

    if isinstance(value, bool):
        return json.dumps(value)
    if isinstance(value, (int, float)):
        n = int(value)
    elif isinstance(value, str):
        if re.fullmatch(r"-?\d+", value):
            n = int(value)
        else:
            return value
    else:
        return json.dumps(value)

    # Heuristic: scale ms->sec
    if abs(n) >= 10_000_000_000:
        n = n // 1000
    try:
        dt = datetime.datetime.fromtimestamp(n, tz=datetime.timezone.utc)
        # Format like "2024-05-21T11:50:13"
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    except (OverflowError, OSError, ValueError):
        # For very large values, chrono in Rust can still produce "+56357-02-19T05:03:..."
        # We'll emulate by using a datetime class that supports extended years.
        return _extended_datetime(n)


def _extended_datetime(secs):
    """Format an extended-year datetime, matching Rust chrono behaviour."""
    import datetime as dt

    try:
        # Python supports years from 1 to 9999.
        base = dt.datetime(1970, 1, 1, tzinfo=dt.timezone.utc)
        d = base + dt.timedelta(seconds=secs)
        return d.strftime("%Y-%m-%dT%H:%M:%S")
    except (OverflowError, OSError, ValueError):
        # Compute manually
        return _calc_extended(secs)


def _calc_extended(secs):
    """Manually compute calendar time for very-large unix seconds."""
    # Days since epoch
    sec_per_day = 86400
    days, remainder = divmod(secs, sec_per_day)
    hours, remainder = divmod(remainder, 3600)
    minutes, seconds = divmod(remainder, 60)
    # Convert days since 1970-01-01 to civil date using Howard Hinnant's algorithm
    z = days + 719468
    era = z // 146097 if z >= 0 else (z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    if m <= 2:
        y += 1
    sign = "+" if y > 9999 else ""
    if y < 0:
        sign = "-"
        y = -y
    return "%s%05d-%02d-%02dT%02d:%02d:%02d" % (sign, y, m, d, hours, minutes, seconds)


# ---------------------------------------------------------------------------
# Value utilities
# ---------------------------------------------------------------------------

def json_value_to_display(value):
    """Convert a JSON value to a display string."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return "null"
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float)):
        # JSON numbers: 1.0 → "1", 1.5 → "1.5"
        if isinstance(value, float) and value.is_integer():
            return str(int(value))
        return json.dumps(value)
    return json.dumps(value)


def value_to_lua_display(value):
    """For --dump-all, scalars and formatted strings. Returns text only."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return "null"
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float)):
        if isinstance(value, float) and value.is_integer():
            # Python's float formatting: 1.0 -> 1
            return repr(value).rstrip("0").rstrip(".") if "." in repr(value) else str(value)
        return repr(value)
    return json.dumps(value)


# ---------------------------------------------------------------------------
# Template engine (subset of handlebars)
# ---------------------------------------------------------------------------

HELPERS = {
    "bold": bold,
    "dim": dim,
    "red": red,
    "green": green,
    "yellow": yellow,
    "blue": blue,
    "purple": purple,
    "cyan": cyan,
    "color_rgb": color_rgb,
    "fixed_size": fixed_size,
    "min_size": min_size,
    "uppercase": uppercase,
    "level_style": level_style,
}


class TemplateError(Exception):
    pass


def _tokenize_template(src):
    """Split into text/tag tokens."""
    tokens = []
    i = 0
    while i < len(src):
        j = src.find("{{", i)
        if j == -1:
            tokens.append(("text", src[i:]))
            break
        if j > i:
            tokens.append(("text", src[i:j]))
        k = src.find("}}", j + 2)
        if k == -1:
            raise TemplateError("unterminated template tag")
        tag = src[j + 2 : k].strip()
        tokens.append(("tag", tag))
        i = k + 2
    return tokens


def _parse_expr(tokens, i):
    """Parse a single expression (variable, literal, or helper call)."""
    tok = tokens[i]
    return tok


def _parse_helper_call(src):
    """Parse a helper call or variable expression.

    Supports:
      var
      helper arg1 arg2 ...
      (helper arg ...)
    Returns an AST node and remaining string.
    """
    s = src.strip()
    node, rest = _parse_call_or_atom(s)
    # If rest is non-empty, we may have args
    return node, rest


def _parse_atom(s):
    s = s.lstrip()
    if not s:
        return None, s
    if s[0] == "(":
        # parenthesized expression
        depth = 0
        for i, ch in enumerate(s):
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    inner = s[1:i]
                    rest = s[i + 1 :]
                    node = _parse_full_expr(inner)
                    return node, rest
        raise TemplateError("unterminated paren")
    if s[0] == '"':
        # string literal
        i = 1
        out = []
        while i < len(s):
            if s[i] == "\\" and i + 1 < len(s):
                out.append(s[i + 1])
                i += 2
                continue
            if s[i] == '"':
                return ("str", "".join(out)), s[i + 1 :]
            out.append(s[i])
            i += 1
        raise TemplateError("unterminated string")
    # number or identifier (may include . >)
    m = re.match(r"[^\s()]+", s)
    if not m:
        return None, s
    token = m.group(0)
    rest = s[m.end() :]
    if re.fullmatch(r"-?\d+(\.\d+)?", token):
        return ("num", float(token) if "." in token else int(token)), rest
    return ("ident", token), rest


def _parse_call_or_atom(s):
    """Parse an atom, then if it's an identifier followed by more atoms, treat as call."""
    node, rest = _parse_atom(s)
    if node is None:
        return None, rest
    if node[0] == "ident" and node[1] in HELPERS:
        args = []
        while True:
            r = rest.lstrip()
            if not r:
                break
            arg, rest = _parse_atom(r)
            if arg is None:
                break
            args.append(arg)
        return ("call", node[1], args), rest
    return node, rest


def _parse_full_expr(s):
    node, rest = _parse_call_or_atom(s)
    if rest.strip():
        raise TemplateError(f"unexpected text: {rest!r}")
    return node


def _eval_node(node, ctx):
    if node is None:
        return ""
    kind = node[0]
    if kind == "str":
        return node[1]
    if kind == "num":
        return node[1]
    if kind == "ident":
        name = node[1]
        return ctx.get(name, "")
    if kind == "call":
        _, fname, args = node
        values = [_eval_node(a, ctx) for a in args]
        fn = HELPERS[fname]
        return fn(*values)
    return ""


def render_template(src, ctx):
    """Render a handlebars-like template.

    Supports:
      {{var}} {{helper args...}} {{(helper args)}} {{#if var}}...{{else}}...{{/if}}
    """
    tokens = _tokenize_template(src)
    return _render_tokens(tokens, 0, ctx)[0]


def _render_tokens(tokens, i, ctx, until=None):
    out = []
    while i < len(tokens):
        kind, val = tokens[i]
        if kind == "text":
            out.append(val)
            i += 1
            continue
        # tag
        if until is not None and val in until:
            return "".join(out), i
        if val.startswith("#if "):
            cond_src = val[len("#if ") :].strip()
            cond_node = _parse_full_expr(cond_src)
            cond_val = _eval_node(cond_node, ctx)
            truthy = bool(cond_val) and cond_val != ""
            then_text, j = _render_tokens(tokens, i + 1, ctx, until={"else", "/if"})
            if j >= len(tokens):
                raise TemplateError("missing /if")
            if tokens[j][1] == "else":
                else_text, k = _render_tokens(tokens, j + 1, ctx, until={"/if"})
                if k >= len(tokens):
                    raise TemplateError("missing /if")
                i = k + 1
            else:
                else_text = ""
                i = j + 1
            out.append(then_text if truthy else else_text)
            continue
        # variable or helper expression
        node = _parse_full_expr(val)
        result = _eval_node(node, ctx)
        out.append(str(result) if not isinstance(result, str) else result)
        i += 1
    return "".join(out), i


# ---------------------------------------------------------------------------
# JSON -> Lua-style value (for filters/print)
# ---------------------------------------------------------------------------

_LUA_SAFE_KEY_RE = re.compile(r"[^a-zA-Z_]")


def sanitize_lua_key(key):
    return _LUA_SAFE_KEY_RE.sub("_", key)


def lua_represent(value):
    """Return the lua representation string and also the python value used for filtering."""
    if value is None:
        return '"unsupported"', "unsupported"
    if isinstance(value, bool):
        return ("true" if value else "false"), value
    if isinstance(value, int):
        return str(value), value
    if isinstance(value, float):
        if value.is_integer():
            return str(int(value)) + ".0" if False else _float_str(value), value
        return _float_str(value), value
    if isinstance(value, str):
        return json.dumps(value), value
    if isinstance(value, dict):
        items = []
        py_items = {}
        for k in sorted(value.keys()):
            inner, pv = lua_represent(value[k])
            sk = sanitize_lua_key(k)
            items.append(f"{sk} = {inner}")
            py_items[sk] = pv
        return "{" + ",".join(items) + "}", py_items
    if isinstance(value, list):
        # Arrays: only support primitives. Nested arrays/objects are "unsupported"
        items = []
        py_items = []
        for v in value:
            if isinstance(v, (dict, list)):
                items.append('"unsupported"')
                py_items.append("unsupported")
            else:
                inner, pv = lua_represent(v)
                items.append(inner)
                py_items.append(pv)
        return "{" + ",".join(items) + "}", py_items
    return '"unsupported"', "unsupported"


def _float_str(f):
    if f.is_integer():
        # Rust prints "1.0" for Number that's float → but in Lua print it prints "1"?
        return str(int(f))
    return repr(f)


# ---------------------------------------------------------------------------
# Flattening for -d dump
# ---------------------------------------------------------------------------

def flatten_values(value, prefix="", depth=0, in_array=False):
    """Yield (path, value) pairs. Uses the Lua-table indexing quirk:
    Outermost array uses 0-indexing; nested arrays use 1-indexing.
    """
    if isinstance(value, dict):
        for k in value:
            kpath = f"{prefix} > {k}" if prefix else k
            yield from flatten_values(value[k], kpath, depth=0, in_array=False)
    elif isinstance(value, list):
        start = 0 if not in_array else 1
        for idx, v in enumerate(value):
            i = idx + start
            new_prefix = f"{prefix}[{i}]"
            yield from flatten_values(v, new_prefix, depth=depth + 1, in_array=True)
    else:
        yield prefix, value


# ---------------------------------------------------------------------------
# Main logic
# ---------------------------------------------------------------------------

DEFAULT_CONFIG = {
    "message_keys": ["short_message", "msg", "message"],
    "time_keys": ["timestamp", "time", "@timestamp"],
    "dump_all_exclude": [],
    "always_print_fields": [],
    "level_keys": ["level", "severity", "log.level", "loglevel"],
    "main_line_format": (
        "{{bold(fixed_size 19 fblog_timestamp)}} "
        "{{level_style (uppercase (fixed_size 5 fblog_level))}}:"
        "{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} "
        "{{fblog_message}}"
    ),
    "additional_value_format": (
        "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}"
    ),
    "level_map": {},
}


def load_config(config_file=None):
    cfg = {k: (list(v) if isinstance(v, list) else dict(v) if isinstance(v, dict) else v) for k, v in DEFAULT_CONFIG.items()}
    if config_file is None:
        # Try standard locations
        candidates = []
        xdg = os.environ.get("XDG_CONFIG_HOME")
        home = os.environ.get("HOME", "")
        if xdg:
            candidates.append(os.path.join(xdg, "fblog.toml"))
            candidates.append(os.path.join(xdg, "fblog", "fblog.toml"))
        if home:
            candidates.append(os.path.join(home, ".config", "fblog.toml"))
            candidates.append(os.path.join(home, ".config", "fblog", "fblog.toml"))
        for c in candidates:
            if os.path.isfile(c):
                config_file = c
                break
    if config_file is not None:
        try:
            import tomli
        except ImportError:
            print("\x1b[31mFailed to load config: tomli not installed.\x1b[0m", file=sys.stderr)
            sys.exit(1)
        try:
            with open(config_file, "rb") as f:
                loaded = tomli.load(f)
        except Exception as exc:
            # panic-like: emulate behaviour in original
            sys.stderr.write("\n")
            sys.stderr.write("thread 'main' panicked at src/main.rs:35:50:\n")
            sys.stderr.write("Could not load config file.\n")
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)
        for k, v in loaded.items():
            cfg[k] = v
    return cfg


def extract_first(data, keys):
    for k in keys:
        if isinstance(data, dict) and k in data:
            return data[k]
    return None


def detect_message(data, message_keys):
    """Find the first matching message key."""
    v = extract_first(data, message_keys)
    if v is None:
        return ""
    return json_value_to_display(v)


def detect_timestamp(data, time_keys):
    v = extract_first(data, time_keys)
    if v is None:
        return ""
    return format_timestamp(v)


def detect_level(data, level_keys, level_map):
    v = extract_first(data, level_keys)
    if v is None:
        return "unknown"
    s = json_value_to_display(v)
    return level_map.get(s, s)


# ---------------------------------------------------------------------------
# Filter (subset Lua evaluator)
# ---------------------------------------------------------------------------

class FilterError(Exception):
    pass


def eval_filter(expr, variables, implicit_return=True, print_lua=False):
    """Evaluate a simple Lua-like filter expression. Returns True/False."""
    # Very limited subset: just transform and eval as Python.
    # If implicit_return, prepend "return "
    src = expr
    if implicit_return:
        src = "return " + src
    # Convert Lua syntax -> Python
    py_expr = _lua_to_python(src, variables)
    try:
        result = eval(py_expr, {"__builtins__": {}}, _filter_globals(variables))
    except Exception as exc:
        msg = f"SyntaxError {{ message: \"src/filter.rs:23:1: {exc}\", incomplete_input: false }}"
        raise FilterError(msg)
    return bool(result)


def _filter_globals(variables):
    # provide string.find etc
    class StringLib:
        @staticmethod
        def find(s, pat, *args):
            import re as _re
            m = _re.search(_lua_pat_to_re(pat), s)
            if m:
                return m.start() + 1, m.end()
            return None

        @staticmethod
        def match(s, pat, *args):
            import re as _re
            m = _re.search(_lua_pat_to_re(pat), s)
            if m:
                return m.group(0)
            return None

        @staticmethod
        def lower(s):
            return s.lower() if s is not None else None

        @staticmethod
        def upper(s):
            return s.upper() if s is not None else None

        @staticmethod
        def len(s):
            return len(s) if s is not None else None

    g = dict(variables)
    g["string"] = StringLib()
    g["nil"] = None
    g["true"] = True
    g["false"] = False
    return g


def _lua_pat_to_re(pat):
    """Convert Lua pattern to Python regex (very minimal)."""
    out = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == "%":
            if i + 1 < len(pat):
                nc = pat[i + 1]
                # escape
                if nc == "d":
                    out.append(r"\d")
                elif nc == "s":
                    out.append(r"\s")
                elif nc == "w":
                    out.append(r"\w")
                else:
                    out.append(re.escape(nc))
                i += 2
                continue
        out.append(c)
        i += 1
    return "".join(out)


_LUA_REPLS = [
    (re.compile(r"~="), "!="),
    (re.compile(r"\bnil\b"), "None"),
    (re.compile(r"\bnot\b"), "not "),
    (re.compile(r"\band\b"), "and"),
    (re.compile(r"\bor\b"), "or"),
]


def _lua_to_python(src, variables):
    s = src
    for rx, rep in _LUA_REPLS:
        s = rx.sub(rep, s)
    return s


# ---------------------------------------------------------------------------
# Context substitution
# ---------------------------------------------------------------------------

def substitute_context(message, context, placeholder_format="{key}"):
    """Replace placeholders in message with values from context."""
    # Build regex from placeholder_format
    esc = re.escape(placeholder_format)
    pat = esc.replace(re.escape("key"), "(.*?)")
    rx = re.compile(pat)

    def _lookup(key, ctx):
        if ctx is None:
            return None, False
        if isinstance(ctx, list):
            try:
                idx = int(key)
            except ValueError:
                return None, False
            if 0 <= idx < len(ctx):
                return ctx[idx], True
            return None, False
        if isinstance(ctx, dict):
            if key in ctx:
                return ctx[key], True
        return None, False

    def repl(m):
        key = m.group(1)
        val, found = _lookup(key, context)
        if not found:
            # Missing key: dim braces + red key
            return dim(placeholder_format.split("key")[0]) + red(bold(key)) + dim(placeholder_format.split("key")[1])
        return format_value_colored(val)

    return rx.sub(repl, message)


def format_value_colored(value):
    if isinstance(value, bool):
        return green(bold("true")) if value else red(bold("false"))
    if isinstance(value, (int, float)):
        if isinstance(value, float) and value.is_integer():
            return cyan(bold(str(int(value))))
        return cyan(bold(str(value)))
    if value is None:
        return dim("null")
    if isinstance(value, str):
        return yellow(bold(value))
    if isinstance(value, list):
        parts = [format_value_colored(v) for v in value]
        return dim("[") + dim(", ").join(parts) + dim("]")
    if isinstance(value, dict):
        parts = []
        for k in sorted(value.keys()):
            parts.append(purple(k) + dim(": ") + format_value_colored(value[k]))
        return dim("{") + dim(", ").join(parts) + dim("}")
    return str(value)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def make_parser():
    p = argparse.ArgumentParser(
        prog="executable",
        description="json log viewer",
        add_help=False,
    )
    p.add_argument("input", nargs="?", default="-")
    p.add_argument("-a", "--additional-value", action="append", default=[])
    p.add_argument("--config-file", default=None)
    p.add_argument("-m", "--message-key", action="append", default=[])
    p.add_argument("--print-lua", action="store_true")
    p.add_argument("-t", "--time-key", action="append", default=[])
    p.add_argument("-l", "--level-key", action="append", default=[])
    p.add_argument("--map-level", action="append", default=[])
    p.add_argument("-d", "--dump-all", action="store_true")
    p.add_argument("-x", "--excluded-value", action="append", default=[])
    p.add_argument("-p", "--with-prefix", action="store_true")
    p.add_argument("-f", "--filter", default=None)
    p.add_argument("--no-implicit-filter-return-statement", action="store_true")
    p.add_argument("--main-line-format", default=None)
    p.add_argument("--additional-value-format", default=None)
    p.add_argument("-s", "--substitute", action="store_true")
    p.add_argument("-c", "--context-key", default=None)
    p.add_argument("-F", "--placeholder-format", default="{key}")
    p.add_argument("-h", "--help", action="store_true")
    p.add_argument("-V", "--version", action="store_true")
    return p


HELP_TEXT = """json log viewer

Usage: executable [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Sets the input file to use, otherwise assumes stdin [default: -]

