          Print version
"""


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    parser = make_parser()
    args = parser.parse_args(argv)

    if args.help:
        sys.stdout.write(HELP_TEXT)
        return 0
    if args.version:
        sys.stdout.write("fblog 4.17.0\n")
        return 0

    cfg = load_config(args.config_file)

    # Apply CLI overrides
    message_keys = list(args.message_key) + list(cfg["message_keys"])
    time_keys = list(args.time_key) + list(cfg["time_keys"])
    level_keys = list(args.level_key) + list(cfg["level_keys"])
    level_map = dict(cfg.get("level_map", {}))
    for m in args.map_level:
        if "=" in m:
            k, v = m.split("=", 1)
            level_map[k] = v

    main_line_format = args.main_line_format or cfg["main_line_format"]
    additional_value_format = args.additional_value_format or cfg["additional_value_format"]
    dump_all_exclude = list(cfg.get("dump_all_exclude", []))
    always_print_fields = list(cfg.get("always_print_fields", []))

    additional_values = list(args.additional_value)
    excluded_values = list(args.excluded_value)
    dump_all = args.dump_all or bool(excluded_values)

    substitute = args.substitute or (args.context_key is not None)
    context_key = args.context_key or "context"
    placeholder_format = args.placeholder_format

    # Read input
    if args.input == "-":
        stream = _stdin_lines()
    else:
        if not os.path.isfile(args.input):
            sys.stderr.write("\n")
            sys.stderr.write(f"thread 'main' panicked at src/main.rs:105:68:\nCan't open file: {args.input}\n")
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            return 101
        stream = _file_lines(args.input)

    for line in stream:
        process_line(
            line,
            message_keys=message_keys,
            time_keys=time_keys,
            level_keys=level_keys,
            level_map=level_map,
            main_line_format=main_line_format,
            additional_value_format=additional_value_format,
            additional_values=additional_values,
            dump_all=dump_all,
            dump_all_exclude=dump_all_exclude + excluded_values,
            always_print_fields=always_print_fields,
            with_prefix=args.with_prefix,
            filter_expr=args.filter,
            no_implicit_return=args.no_implicit_filter_return_statement,
            print_lua=args.print_lua,
            substitute=substitute,
            context_key=context_key,
            placeholder_format=placeholder_format,
        )
    return 0


def _stdin_lines():
    # Read bytes to handle invalid UTF-8 gracefully
    raw = sys.stdin.buffer
    buf = b""
    while True:
        chunk = raw.readline()
        if not chunk:
            break
        # strip newline
        if chunk.endswith(b"\n"):
            chunk = chunk[:-1]
        if chunk.endswith(b"\r"):
            chunk = chunk[:-1]
        try:
            yield chunk.decode("utf-8")
        except UnicodeDecodeError:
            yield _InvalidLine()


class _InvalidLine(str):
    pass


def _file_lines(path):
    with open(path, "rb") as f:
        for line in f:
            if line.endswith(b"\n"):
                line = line[:-1]
            if line.endswith(b"\r"):
                line = line[:-1]
            try:
                yield line.decode("utf-8")
            except UnicodeDecodeError:
                yield _InvalidLine()


def process_line(
    line,
    *,
    message_keys,
    time_keys,
    level_keys,
    level_map,
    main_line_format,
    additional_value_format,
    additional_values,
    dump_all,
    dump_all_exclude,
    always_print_fields,
    with_prefix,
    filter_expr,
    no_implicit_return,
    print_lua,
    substitute,
    context_key,
    placeholder_format,
):
    orange = lambda t: bold(color_rgb(255, 135, 22, t))

    if isinstance(line, _InvalidLine):
