    ('level == "info"', True),
    ('level ~= "info"', False),
    ('n > 3', True),
    ('tags[0] == "a"', False),
    ('tags[1] == "a"', True),
    ('tags[2] == "b"', True),
    ('string.lower(m) == "hello"', True),
    ('string.upper("abc") == "ABC"', True),
    ('string.len(m) == 5', True),
    ('m:find("ell") ~= nil', True),   # method call
]
inp = '{"level": "info", "n": 5, "tags": ["a", "b"], "m": "HELLO"}\n'
for expr, _ in tests:
    r1 = subprocess.run(["python3", "src/fblog.py", "-f", expr], input=inp, capture_output=True, text=True)
    r2 = subprocess.run(["./executable", "-f", expr], input=inp, capture_output=True, text=True)
    if r1.stdout != r2.stdout:
        print(f"DIFF for {expr}:")
        print(f"  mine: {r1.stdout!r}")
        print(f"  orig: {r2.stdout!r}")
print("done")
